INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-01', 'a1-05', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Cómo está Laura sintiéndose?', '["happy","tired","angry"]', '{"correct":"tired"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-02', 'a1-05', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Está Laura enferma?', '["Yes","No","Maybe"]', '{"correct":"No"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-03', 'a1-05', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Está Tom presente en la conversación?', '["Yes","No","We don''t know"]', '{"correct":"No"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-04', 'a1-05', '10204', 'multiple_choice', 'Escucha el diálogo y responde: Cómo está Tom sintiéndose?', '["happy","fine","sad"]', '{"correct":"sad"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-05', 'a1-05', '10205', 'multiple_choice', 'Escucha el diálogo y responde: Cuál es la negativa de ''Yo estoy feliz''?', '["I am not happy","Am I happy?","I is not happy"]', '{"correct":"I am not happy"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
