INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-07', 'a1-05', '10207', 'multiple_choice', 'Escucha el diálogo y responde: Cuál es la corta respuesta a ''Estás tú cansado? — Sí''?', '["Yes, I is.","Yes, I am.","Yes, I are."]', '{"correct":"Yes, I am."}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-08', 'a1-05', '10208', 'multiple_choice', 'Escucha el diálogo y responde: Cuál palabra significa ''Hambriento''?', '["Thirsty","Angry","Hungry"]', '{"correct":"Hungry"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u05-lis-09', 'a1-05', '10209', 'multiple_choice', 'Escucha el diálogo y responde: Cuál es la negativa de ''Ella es feliz''?', '["She isn''t happy","She aren''t happy","She amn''t happy"]', '{"correct":"She isn''t happy"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
