INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u13-lis-10', 'a1-13', '10210', 'multiple_choice', 'Escucha el diálogo y responde: Cuál es el día después de miércoles?', '["Tuesday","Thursday","Friday"]', '{"correct":"Thursday"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
