INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-01', 'a1-14', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Qué día es hoy en la conversación?', '["Monday","Wednesday","Friday"]', '{"correct":"Wednesday"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-02', 'a1-14', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Cuándo es la prueba?', '["Today","Tomorrow","On Friday"]', '{"correct":"Tomorrow"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-03', 'a1-14', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Trabaja el hablante trabaja los sábados?', '["Yes","No","Sometimes"]', '{"correct":"No"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-04', 'a1-14', '10204', 'multiple_choice', 'Escucha el diálogo y responde: Qué hace el hablante hace los fines de semana?', '["Works","Relaxes at home","Goes to the gym"]', '{"correct":"Relaxes at home"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-05', 'a1-14', '10205', 'multiple_choice', 'Escucha el diálogo y responde: Cuál preposición va antes de [[days|días] ] de la semana?', '["at","in","on"]', '{"correct":"on"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-06', 'a1-14', '10206', 'multiple_choice', 'Escucha el diálogo y responde: Cómo se dice tú dices ''Miércoles'' en inglés?', '["Tuesday","Thursday","Wednesday"]', '{"correct":"Wednesday"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u14-lis-07', 'a1-14', '10207', 'multiple_choice', 'Escucha el diálogo y responde: Qué significa ''Weekend'' significa?', '["Monday to Friday","Saturday and Sunday","Any free day"]', '{"correct":"Saturday and Sunday"}', 'Transcripción: What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?', 'listening', 'What day is it today? It is Wednesday. We have a test tomorrow. Do you work on Saturdays? No, I don''t work on weekends. I relax at home. That sounds great! What do you do on Fridays?');
