INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u16-lis-01', 'a1-16', '10201', 'multiple_choice', 'Escucha el diálogo y responde: A dónde fue el hablante fue de vacaciones?', '["Spain","Italy","Greece"]', '{"correct":"Greece"}', 'Transcripción: How was your holidays? Where did you go? They were amazing! I went to Greece. Wow! Was the weather good? It was perfect — hot and sunny every day. The beaches were beautiful and the local food was delicious. It sounds like a perfect holiday! Did you buy any souvenirs?', 'listening', 'How was your holidays? Where did you go? They were amazing! I went to Greece. Wow! Was the weather good? It was perfect — hot and sunny every day. The beaches were beautiful and the local food was delicious. It sounds like a perfect holiday! Did you buy any souvenirs?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u16-lis-02', 'a1-16', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Cómo fue el tiempo?', '["Rainy and cold","Hot and sunny","Cloudy and windy"]', '{"correct":"Hot and sunny"}', 'Transcripción: How was your holidays? Where did you go? They were amazing! I went to Greece. Wow! Was the weather good? It was perfect — hot and sunny every day. The beaches were beautiful and the local food was delicious. It sounds like a perfect holiday! Did you buy any souvenirs?', 'listening', 'How was your holidays? Where did you go? They were amazing! I went to Greece. Wow! Was the weather good? It was perfect — hot and sunny every day. The beaches were beautiful and the local food was delicious. It sounds like a perfect holiday! Did you buy any souvenirs?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u16-lis-03', 'a1-16', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Cómo describe el hablante describe las playas?', '["Crowded","Beautiful","Dirty"]', '{"correct":"Beautiful"}', 'Transcripción: How was your holidays? Where did you go? They were amazing! I went to Greece. Wow! Was the weather good? It was perfect — hot and sunny every day. The beaches were beautiful and the local food was delicious. It sounds like a perfect holiday! Did you buy any souvenirs?', 'listening', 'How was your holidays? Where did you go? They were amazing! I went to Greece. Wow! Was the weather good? It was perfect — hot and sunny every day. The beaches were beautiful and the local food was delicious. It sounds like a perfect holiday! Did you buy any souvenirs?');
