INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u18-lis-01', 'a1-18', '10201', 'multiple_choice', 'Escucha el diálogo y responde: A qué hora se despierta el hablante despierta arriba?', '["Six o''clock","Six thirty","Seven o''clock"]', '{"correct":"Six thirty"}', 'Transcripción: Can you describe your daily routine? Sure! First, I wake up at six thirty. Then, I take a shower and get dressed. After that, I have breakfast — usually toast and coffee. Finally, I go to work at eight o''clock.', 'listening', 'Can you describe your daily routine? Sure! First, I wake up at six thirty. Then, I take a shower and get dressed. After that, I have breakfast — usually toast and coffee. Finally, I go to work at eight o''clock.');
