INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u29-lis-01', 'a1-29', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Cómo está Laura sintiéndose?', '["happy","tired","angry"]', '{"correct":"tired"}', 'Transcripción: Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.', 'listening', 'Hi Laura! How are you? I am not very well. I am tired. Are you sick? No, I am not sick. Just very tired. Is Tom here? Is he happy? No, he is not here. He is sad today.');
