INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u33-lis-01', 'a1-33', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Cuál es el del hablante trabajo?', '["teacher","doctor","engineer"]', '{"correct":"doctor"}', 'Transcripción: What do you do for work? I am a doctor. I work in the city hospital. That is interesting! Does your wife work too? Yes, she is a teacher. She teaches at the primary school. And what about your children? My son is a student and my daughter wants to be a pilot.', 'listening', 'What do you do for work? I am a doctor. I work in the city hospital. That is interesting! Does your wife work too? Yes, she is a teacher. She teaches at the primary school. And what about your children? My son is a student and my daughter wants to be a pilot.');
