INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u38-lis-01', 'a1-38', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Ve el hablante ve televisión cada noche?', '["Yes, always","Sometimes","No, never"]', '{"correct":"Sometimes"}', 'Transcripción: Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.', 'listening', 'Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u38-lis-02', 'a1-38', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Qué hace el hablante normalmente hace por la noche?', '["Watches TV","Listens to music","Exercises"]', '{"correct":"Listens to music"}', 'Transcripción: Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.', 'listening', 'Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u38-lis-03', 'a1-38', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Cuántas muchas veces van ellos van al al gimnasio por semana?', '["Twice","Four times","Three times"]', '{"correct":"Three times"}', 'Transcripción: Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.', 'listening', 'Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u38-lis-04', 'a1-38', '10204', 'multiple_choice', 'Escucha el diálogo y responde: Cómo se conocen ellos se encuentran?', '["They call first","They meet at the gym","They go together"]', '{"correct":"They meet at the gym"}', 'Transcripción: Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.', 'listening', 'Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u38-lis-05', 'a1-38', '10205', 'multiple_choice', 'Escucha el diálogo y responde: Cuál es la negativa de ''I work on Mondays''?', '["I don''t work on Mondays","I doesn''t work on Mondays","I am not work on Mondays"]', '{"correct":"I don''t work on Mondays"}', 'Transcripción: Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.', 'listening', 'Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u38-lis-06', 'a1-38', '10206', 'multiple_choice', 'Escucha el diálogo y responde: Cómo formas tú formas una pregunta con ''Do''?', '["Do + subject + verb?","Does + subject + verb?","Is + subject + verb?"]', '{"correct":"Do + subject + verb?"}', 'Transcripción: Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.', 'listening', 'Do you watch TV in the evening? Sometimes, but I usually listen to music. Do you and your friends exercise together? Yes! We go to the gym three times a week. We don''t call each other — we just meet there.');
