INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u44-lis-01', 'a1-44', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Qué color es el libro?', '["Red","Blue","Green"]', '{"correct":"Blue"}', 'Transcripción: Look at this! What is this? It is a book. It is blue. How many pens do you have? I have three pens. Two are red and one is blue. What about notebooks? I have one notebook. It is new.', 'listening', 'Look at this! What is this? It is a book. It is blue. How many pens do you have? I have three pens. Two are red and one is blue. What about notebooks? I have one notebook. It is new.');
