INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u45-lis-01', 'a1-45', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Cuántos muchos dormitorios tiene la casa tiene?', '["Two","Four","Three"]', '{"correct":"Three"}', 'Transcripción: Tell me about your house. What rooms does it have? We have a large living room, a kitchen, three bedrooms and two bathrooms. Oh, that''s spacious! Is there a garden? Yes! We have a small garden with flowers and a table outside. My favourite room is the living room — it''s so bright and cozy!', 'listening', 'Tell me about your house. What rooms does it have? We have a large living room, a kitchen, three bedrooms and two bathrooms. Oh, that''s spacious! Is there a garden? Yes! We have a small garden with flowers and a table outside. My favourite room is the living room — it''s so bright and cozy!');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u45-lis-02', 'a1-45', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Cuántos muchos baños tiene la casa tiene?', '["One","Three","Two"]', '{"correct":"Two"}', 'Transcripción: Tell me about your house. What rooms does it have? We have a large living room, a kitchen, three bedrooms and two bathrooms. Oh, that''s spacious! Is there a garden? Yes! We have a small garden with flowers and a table outside. My favourite room is the living room — it''s so bright and cozy!', 'listening', 'Tell me about your house. What rooms does it have? We have a large living room, a kitchen, three bedrooms and two bathrooms. Oh, that''s spacious! Is there a garden? Yes! We have a small garden with flowers and a table outside. My favourite room is the living room — it''s so bright and cozy!');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u45-lis-03', 'a1-45', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Tiene la casa hay un jardín?', '["No","Yes, a large one","Yes, a small one"]', '{"correct":"Yes, a small one"}', 'Transcripción: Tell me about your house. What rooms does it have? We have a large living room, a kitchen, three bedrooms and two bathrooms. Oh, that''s spacious! Is there a garden? Yes! We have a small garden with flowers and a table outside. My favourite room is the living room — it''s so bright and cozy!', 'listening', 'Tell me about your house. What rooms does it have? We have a large living room, a kitchen, three bedrooms and two bathrooms. Oh, that''s spacious! Is there a garden? Yes! We have a small garden with flowers and a table outside. My favourite room is the living room — it''s so bright and cozy!');
