INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u46-lis-01', 'a1-46', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Es el sofá nuevo?', '["No, it''s old","Yes, it''s new","It''s second-hand"]', '{"correct":"Yes, it''s new"}', 'Transcripción: I love your flat! Is that sofa new? Yes! I bought it last month past. It''s very comfortable. And what about that lamp? Is it yours? No, that lamp is my flatmate''s. The carpet and the curtains are mine, though. I chose them myself.', 'listening', 'I love your flat! Is that sofa new? Yes! I bought it last month past. It''s very comfortable. And what about that lamp? Is it yours? No, that lamp is my flatmate''s. The carpet and the curtains are mine, though. I chose them myself.');
