INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u48-lis-01', 'a1-48', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Hay allí un banco cerca?', '["No","Yes, on the main street","Yes, far away"]', '{"correct":"Yes, on the main street"}', 'Transcripción: Excuse, is there a bank near here? Yes, there is one on the main street. It''s next to the supermarket. Are there any ATMs inside? Yes, there are two ATMs inside and one outside. Is there a café nearby? There isn''t one on my street.', 'listening', 'Excuse, is there a bank near here? Yes, there is one on the main street. It''s next to the supermarket. Are there any ATMs inside? Yes, there are two ATMs inside and one outside. Is there a café nearby? There isn''t one on my street.');
