INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u50-lis-01', 'a1-50', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Qué pide el cliente pide?', '["Tea and biscuits","Coffee and sandwich","Juice and cake"]', '{"correct":"Coffee and sandwich"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
