INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u52-lis-01', 'a1-52', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Qué busca el cliente busca primero primero?', '["Fresh vegetables","The dairy products section","The checkout"]', '{"correct":"The dairy products section"}', 'Transcripción: Excuse me. Do you know where the dairy products are? Yes, they''re in aisle four, next to the frozen food section. Thank you. And where can I find organic vegetables? They''re at the back of the store, near the fresh produce section. Great! Oh and is there a special offer on fish today?', 'listening', 'Excuse me. Do you know where the dairy products are? Yes, they''re in aisle four, next to the frozen food section. Thank you. And where can I find organic vegetables? They''re at the back of the store, near the fresh produce section. Great! Oh and is there a special offer on fish today?');
