INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u53-lis-01', 'a1-53', '10201', 'multiple_choice', 'Escucha el diálogo y responde: A qué transporte quiere el hablante quiere ir?', '["Bus station","Train station","Airport"]', '{"correct":"Train station"}', 'Transcripción: Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?', 'listening', 'Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u53-lis-02', 'a1-53', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Cuántos cuántos minutos tiene el hablante caminar recto?', '["One","Three","Two"]', '{"correct":"Two"}', 'Transcripción: Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?', 'listening', 'Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u53-lis-03', 'a1-53', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Dónde gira el hablante gira a la izquierda?', '["At the crossroads","At the bridge","At the traffic lights"]', '{"correct":"At the traffic lights"}', 'Transcripción: Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?', 'listening', 'Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u53-lis-04', 'a1-53', '10204', 'multiple_choice', 'Escucha el diálogo y responde: Cuál calle toma el hablante toma a la derecha?', '["The first","The third","The second"]', '{"correct":"The second"}', 'Transcripción: Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?', 'listening', 'Excuse, how do I get to the train station? Go straight for two minutes, then turn left at the traffic lights. Then, take the second street on the right. The station is at the end of that road, on the left. Is it far? Can I walk there?');
