INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-01', 'a1-54', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Qué pide el cliente pide?', '["Tea and biscuits","Coffee and sandwich","Juice and cake"]', '{"correct":"Coffee and sandwich"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-02', 'a1-54', '10202', 'multiple_choice', 'Escucha el diálogo y responde: Qué tamaño de café pide el cliente quiere?', '["Small","Medium","Large"]', '{"correct":"Large"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-03', 'a1-54', '10203', 'multiple_choice', 'Escucha el diálogo y responde: Pide el cliente pide algo más?', '["No","Yes, a piece of cake","Yes, another coffee"]', '{"correct":"Yes, a piece of cake"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-04', 'a1-54', '10204', 'multiple_choice', 'Escucha el diálogo y responde: Cuánto cuánto cuesta el pedido cuesta?', '["Six euros","Ten euros","Eight euros"]', '{"correct":"Eight euros"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-05', 'a1-54', '10205', 'multiple_choice', 'Escucha el diálogo y responde: Cómo pides tú educadamente pides por algo en inglés?', '["Give me...","I want...","Can I have...?"]', '{"correct":"Can I have...?"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-06', 'a1-54', '10206', 'multiple_choice', 'Escucha el diálogo y responde: Qué significa ''I''d like'' significa?', '["I like","I would like","I don''t like"]', '{"correct":"I would like"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
