INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-08', 'a1-54', '10208', 'multiple_choice', 'Escucha el diálogo y responde: Qué significa ''Bill'' significa en un restaurante?', '["Menu","Table","Check/Account"]', '{"correct":"Check/Account"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-09', 'a1-54', '10209', 'multiple_choice', 'Escucha el diálogo y responde: Qué significa ''Of course'' significa?', '["No problem","Certainly/Yes","I understand"]', '{"correct":"Certainly/Yes"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u54-lis-10', 'a1-54', '10210', 'multiple_choice', 'Escucha el diálogo y responde: Cómo dice el camarero saluda al cliente?', '["Good afternoon!","Good morning!","Good evening!"]', '{"correct":"Good morning!"}', 'Transcripción: Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.', 'listening', 'Good morning! What can I get you? I''d like a large coffee and a sandwich, please. Of course! Anything else? Yes, can I have a piece of cake, please? That will be eight euros, please.');
