INSERT INTO learning_exercises (id, lesson_id, exercise_number, exercise_type, prompt, options_json, answer_json, explanation, section_type, audio_text) VALUES ('a1-u56-lis-01', 'a1-56', '10201', 'multiple_choice', 'Escucha el diálogo y responde: Cuándo es el del hablante cumpleaños?', '["August 5th","August 15th","August 25th"]', '{"correct":"August 15th"}', 'Transcripción: When is your birthday? My birthday is on the fifteenth of August. That''s in summer! What do you usually do? I usually have a party with my family and friends. And when is Christmas?', 'listening', 'When is your birthday? My birthday is on the fifteenth of August. That''s in summer! What do you usually do? I usually have a party with my family and friends. And when is Christmas?');
